#define SDL_MAIN_HANDLED
#include "ds_audio.h"
#include <cassert>
#include <vector>
#include <cmath>
#include <iostream>
int main(){SDL_SetMainReady();SDL_setenv("SDL_AUDIODRIVER","dummy",1);assert(SDL_Init(SDL_INIT_AUDIO)==0);SDL_AudioSpec spec{};spec.freq=32768;spec.format=AUDIO_S16SYS;spec.channels=2;spec.samples=512;auto device=SDL_OpenAudioDevice(nullptr,0,&spec,nullptr,0);assert(device);DSAudioQueue q;q.configure(device,32768);std::vector<int16_t> music(4096,30000);assert(q.push(music.data(),2048));assert(!q.playing);assert(SDL_GetAudioDeviceStatus(device)==SDL_AUDIO_PAUSED);assert(SDL_GetQueuedAudioSize(device)==8192);assert(q.push(music.data(),2048));assert(q.playing&&SDL_GetAudioDeviceStatus(device)==SDL_AUDIO_PLAYING);SDL_Delay(220);assert(SDL_GetQueuedAudioSize(device)==0);assert(q.push(music.data(),512));assert(q.playing&&q.underruns==1);assert(SDL_GetAudioDeviceStatus(device)==SDL_AUDIO_PLAYING);assert(SDL_GetQueuedAudioSize(device)<=2048);assert(q.push(music.data(),2048));assert(q.playing);assert(q.push(music.data(),1024));assert(q.playing);q.reset();assert(!q.playing&&SDL_GetQueuedAudioSize(device)==0);assert(std::abs(dsAudioFrameInterval(60,0,12000,false)-1./60)<1e-10);assert(dsAudioFrameInterval(60,0,12000,true)<1./60);assert(dsAudioFrameInterval(60,20000,12000,true)>1./60);SDL_CloseAudioDevice(device);SDL_Quit();std::cout<<"PASS: real SDL audio queue prebuffer, underrun refill, state reset and bounded drift pacing\n";return 0;}
